"""Teacher presentation only; authorization and deferred analytics stay in app.py."""
from html import escape
from .theme import stylesheet_html
from .icons import icon_container
from .cards import section_header

TEACHER_CSS = '<style>\n.st-key-bui_teacher_surface{color:#173052;background:#F6F8FC;border:1px solid #E6EAF2;border-radius:24px;padding:clamp(12px,2vw,24px);min-width:0;}\n.st-key-bui_teacher_surface .bui-teacher-header{background:white;border-left:5px solid #4C86DB;border-radius:18px;padding:24px;margin-bottom:24px;box-shadow:0 5px 18px rgba(23,48,82,.06);}\n.st-key-bui_teacher_surface .bui-teacher-header h1{color:#173052;font-size:clamp(24px,3vw,36px);line-height:1.25;margin:16px 0;}\n.st-key-bui_teacher_surface .bui-teacher-header p{color:#526175;}\n.st-key-bui_teacher_surface .bui-teacher-logo{display:block;width:min(280px,100%);height:auto;}\n.st-key-bui_teacher_surface :is(.teacher-card,[data-testid="stMetric"]){background:white!important;color:#173052!important;border:1px solid #E6EAF2!important;border-left:5px solid #33836A!important;border-radius:18px!important;padding:20px!important;box-shadow:0 5px 18px rgba(23,48,82,.06)!important;overflow-wrap:anywhere;}\n.st-key-bui_teacher_surface [data-testid="stColumn"]:nth-child(2) [data-testid="stMetric"]{border-left-color:#8462C3!important;}\n.st-key-bui_teacher_surface [data-testid="stColumn"]:nth-child(3) [data-testid="stMetric"]{border-left-color:#D6A12D!important;}\n.st-key-bui_teacher_surface :is([data-testid="stMetricValue"],[data-testid="stMetricLabel"]){color:#173052!important;}\n.st-key-bui_teacher_surface [data-testid="stButton"] button{min-height:44px;color:#173052;border-radius:10px;border:1px solid #173052;}\n.st-key-bui_teacher_surface [data-testid="stButton"] button[kind="primary"]{background:#DF73A0!important;color:#102642!important;}\n.st-key-bui_teacher_surface [data-testid] :is(button,input,[role="combobox"],summary):focus-visible{outline:3px solid #173052!important;outline-style:solid!important;outline-offset:3px;}\n.st-key-bui_teacher_surface [data-testid="stExpander"]{background:white;border-radius:12px;border-left:4px solid #D6A12D;}\n.st-key-bui_teacher_surface [data-testid="stHorizontalBlock"]{flex-wrap:wrap!important;min-width:0;}\n.st-key-bui_teacher_surface [data-testid="stColumn"]{flex:1 1 180px!important;min-width:0!important;}\nbody:has(.st-key-bui_teacher_surface) [data-testid="stSidebar"]{background:#F6F8FC;}\nbody:has(.st-key-bui_teacher_surface) [data-testid="stSidebar"] button{min-height:44px;color:#173052;border-radius:10px;border:1px solid #E6EAF2;border-left:4px solid #4C86DB;background:white;}\nbody:has(.st-key-bui_teacher_surface) [data-testid="stSidebar"] button:focus-visible{outline:3px solid #173052!important;outline-style:solid!important;outline-offset:3px;}\n@media(max-width:768px){.st-key-bui_teacher_surface [data-testid="stColumn"]{width:100%!important;flex:1 1 100%!important;min-width:0!important;}.st-key-bui_teacher_surface .bui-teacher-header{padding:16px;}}\n</style>'

def render_teacher_header(st, logo_uri):
    st.html(stylesheet_html() + TEACHER_CSS)
    st.markdown('<header class="bunseki-ui bui-teacher-header"><img class="bui-teacher-logo" src="' + escape(logo_uri, quote=True) + '" alt="BunsekiChat">' + icon_container("subjects") + '<h1>Espacio docente BunsekiChat</h1><p>Resumen, planificación y acompañamiento de tus asignaciones académicas.</p></header>', unsafe_allow_html=True)
    st.markdown(section_header("Trabajo académico", "Navega por las herramientas existentes de tus cursos y paralelos.", icon="assessment"), unsafe_allow_html=True)
